referenceSolutions.python:
def switchboardRingsFirstQualifyingSlip(links, k):
    a=links
    out=[]
    from collections import deque
    n=len(a)
    dist=[-1]*n
    queue=deque()
    if n:
        dist[0]=0
        queue.append(0)
    while queue:
        u=queue.popleft()
        for v in range(n):
            if a[u][v] and dist[v]==-1:
                dist[v]=dist[u]+1
                queue.append(v)
    out=dist
    return next((x for x in out if x>=k),-1)

